const paths = ["guidance/docs/agents/architecture-checkpoints.md", "guidance/docs/adr/0001-reusable-harness-and-local-integration.md", "guidance/docs/adr/0002-human-qa-gates-feature-promotion.md", "cases/a3/CONTRACT.md","cases/a3/qa.py","cases/a3/run.py","cases/b7/CONTRACT.md","cases/b7/git_ops.py","cases/b7/caller.py","cases/c2/CONTRACT.md","cases/c2/checking.py","cases/c2/execution.py"];
const results = await Promise.allSettled(paths.map(path => tools.exec_command({cmd:`nl -ba /tmp/development-review-19-c3/${path}`,max_output_tokens:12000})));
results.forEach((result, i)=>text({path:paths[i], result}));

const paths = ["cases/d9/CONTRACT.md","cases/d9/plan.py","cases/e4/CONTRACT.md","cases/e4/attempt.py","cases/e4/repair.py","cases/e4/worker.py","cases/f6/CONTRACT.md","cases/f6/io_ops.py","cases/g1/CONTRACT.md","cases/g1/cli.py","cases/g1/preparation.py","cases/g1/resume.py","cases/h8/CONTRACT.md","cases/h8/attempt.py","cases/h8/caller.py"];
const results = await Promise.allSettled(paths.map(path => tools.exec_command({cmd:`nl -ba /tmp/development-review-19-c3/${path}`,max_output_tokens:12000})));
results.forEach((result, i)=>text({path:paths[i], result}));

const result = await tools.exec_command({cmd:"rg --files | sort | xargs sha256sum",workdir:"/tmp/development-review-19-c3",max_output_tokens:12000});
text(result);
const manifest = Object.fromEntries(result.output.trim().split("\n").map(line=>[line.slice(66), line.slice(0,64)]));
store("manifest", manifest);
const entries = Object.keys(manifest).sort().map(path=>JSON.stringify(path)+": "+JSON.stringify(manifest[path]));
const spaced = "{"+entries.join(", ")+"}";
store("manifestJson", spaced);
text(await tools.exec_command({cmd:"printf '%s' '"+spaced.replaceAll("'","'\\''")+"' | sha256sum",max_output_tokens:1000}));

const manifest=load("manifest");
const compact=JSON.stringify(Object.fromEntries(Object.keys(manifest).sort().map(k=>[k,manifest[k]])));
const forms=[["compact",compact],["spaced-newline",load("manifestJson")+"\n"],["compact-newline",compact+"\n"]];
const results=await Promise.allSettled(forms.map(([name,body])=>tools.exec_command({cmd:"printf '%s' '"+body.replaceAll("'","'\\''")+"' | sha256sum",max_output_tokens:1000})));
results.forEach((r,i)=>text({form:forms[i][0],result:r}));
store("compactManifestJson", compact);

const result=await tools.exec_command({cmd:"rg --files --hidden --no-ignore | sort | xargs sha256sum",workdir:"/tmp/development-review-19-c3",max_output_tokens:12000});
text(result);
const manifest=Object.fromEntries(result.output.trim().split("\n").map(line=>[line.slice(66),line.slice(0,64)]));
store("manifestAll",manifest);
const spaced="{"+Object.keys(manifest).sort().map(path=>JSON.stringify(path)+": "+JSON.stringify(manifest[path])).join(", ")+"}";
store("manifestAllJson",spaced);
text(await tools.exec_command({cmd:"printf '%s' '"+spaced.replaceAll("'","'\\''")+"' | sha256sum",max_output_tokens:1000}));

const corrected=load("report").replace("contains 35 files: REVIEW.md, eight contracts, 15 Python files","contains 36 files: REVIEW.md, eight contracts, 16 Python files").replace("All 15 Python files were assessed","All 16 Python files were assessed");
store("report",corrected);
text(await tools.apply_patch("*** Begin Patch\n*** Update File: /tmp/development-review-19-spec-c3-report.md\n@@\n-2. The complete inventory contains 35 files: REVIEW.md, eight contracts, 15 Python files, three Standards-only skill files and eight other guidance documents. All 15 Python files were assessed; the three Standards-only skills were hashed for identity without importing their requirements into this Spec axis.\n+2. The complete inventory contains 36 files: REVIEW.md, eight contracts, 16 Python files, three Standards-only skill files and eight other guidance documents. All 16 Python files were assessed; the three Standards-only skills were hashed for identity without importing their requirements into this Spec axis.\n*** End Patch"));
text(await tools.exec_command({cmd:"printf '%s' '"+load("manifestAllJson").replaceAll("'","'\\''")+"' > /tmp/development-review-19-spec-c3-manifest.json",max_output_tokens:1000}));
text(await tools.exec_command({cmd:"sha256sum /tmp/development-review-19-spec-c3-report.md /tmp/development-review-19-spec-c3-manifest.json > /tmp/development-review-19-spec-c3-audit.sha256",max_output_tokens:1000}));
text(await tools.exec_command({cmd:"cat /tmp/development-review-19-spec-c3-audit.sha256",max_output_tokens:1000}));
text({inventoryCount:Object.keys(load("manifestAll")).length,pythonCount:Object.keys(load("manifestAll")).filter(path=>path.endsWith(".py")).length});
